{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "EC2 Instance with Public IP Address",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The configuration explicitly associates a public IP address to one of the instances (count.index == 1), exposing it directly to the internet which increases the attack surface."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 Instance without IMDSv2 Enforcement",
      "resource": "aws_instance.ubuntu",
      "severity": "LOW",
      "explanation": "The instance does not enforce IMDSv2 (metadata service version 2), leaving it vulnerable to Server-Side Request Forgery (SSRF) attacks that can steal IAM credentials via the metadata endpoint."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Disabled public IP association for all instances to reduce network exposure and added `metadata_options` to enforce IMDSv2, mitigating SSRF risks."
}
